import React from 'react';

const Timeline = () => {
    const events = [
        { year: 1917, description: "Inicio de la dictadura: Federico Tinoco asumió el poder mediante un golpe de Estado." },
        { year: "1917–1918", description: "Consolidación del régimen: La dictadura fortaleció su control político y limitó libertades." },
        { year: "1918–1919", description: "Oposición y descontento social: Surgieron manifestaciones de oposición política y social." },
        { year: 1919, description: "Fin de la dictadura: La caída del régimen marcó un momento importante en la historia política costarricense." },
    ];

    return (
        <div className="timeline">
            <h2>Línea de Tiempo</h2>
            <ul>
                {events.map((event, index) => (
                    <li key={index}>
                        <strong>{event.year}</strong>: {event.description}
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default Timeline;
